package com.slayerswaps;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * A small box saying where teleports go right now and which teleport to use next.
 */
class DestinationOverlay extends OverlayPanel
{
	private final SlayerSwapsPlugin plugin;
	private final SlayerSwapsConfig config;

	@Inject
	DestinationOverlay(SlayerSwapsPlugin plugin, SlayerSwapsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showDestination())
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(ComponentConstants.STANDARD_WIDTH, 0));
		String task = plugin.taskName();
		String prompt = plugin.choicePrompt();
		if (prompt != null)
		{
			// With no task, the master being set up (the teleport back to them), or "No task" before one is chosen
			String title = task != null ? task : config.slayerMaster() == SlayerMaster.NOT_CHOSEN ? "No task"
				: "Back to " + config.slayerMaster();
			line(graphics, title, config.highlightColor());
			line(graphics, "Right-click your slayer helmet", Color.WHITE);
			line(graphics, prompt, Color.WHITE);
			return super.render(graphics);
		}

		SlayerData.Route next = plugin.nextRoute();
		String location = plugin.currentLocation();
		if (location != null && plugin.nearObjective() && !plugin.atTask())
		{
			// Close enough to walk: no more teleports
			line(graphics, task != null ? task : "Back to " + config.slayerMaster(), config.highlightColor());
			line(graphics, Routes.place(location), Color.WHITE);
			String note = plugin.walkNote();
			if (note != null)
			{
				line(graphics, Character.toUpperCase(note.charAt(0)) + note.substring(1), config.highlightColor());
			}
			return super.render(graphics);
		}
		if (next == null || location == null)
		{
			return null;
		}

		line(graphics, task != null ? task : "Back to " + config.slayerMaster(), config.highlightColor());
		// Centred lines under the centred task name, with any step after arriving (like pulling a lever) underneath
		line(graphics, Routes.place(location), Color.WHITE);
		line(graphics, describe(next), config.highlightColor());
		// Only the step to take now: after going home, the box shows the step in the house
		if (next.getNote() != null && next.routeType() != RouteType.PORTAL)
		{
			line(graphics, "then " + next.getNote(), Color.WHITE);
		}
		return super.render(graphics);
	}

	private String describe(SlayerData.Route next)
	{
		// In the house, a portal chamber portal, portal nexus or jewellery box does the job
		String portal = plugin.housePortalOption(next);
		if (portal != null)
		{
			return "Portal : " + portal;
		}
		String nexus = plugin.nexusOption(next);
		if (nexus != null)
		{
			return "Nexus : " + nexus;
		}
		String jewellery = plugin.jewelleryBoxOption(next);
		return jewellery != null ? "Jewellery box : " + jewellery : Routes.describeTeleport(plugin.data(), next);
	}

	/**
	 * Adds a centred line, widening the box to fit it so longer teleports don't run outside it.
	 */
	private void line(Graphics2D graphics, String text, Color color)
	{
		panelComponent.getChildren().add(TitleComponent.builder().text(text).color(color).build());
		int width = graphics.getFontMetrics().stringWidth(text) + 10;
		if (width > panelComponent.getPreferredSize().width)
		{
			panelComponent.setPreferredSize(new Dimension(width, 0));
		}
	}
}

package com.slayerswaps;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines the destination to pick in open teleport menus.
 */
class MenuHighlightOverlay extends Overlay
{
	private final MenuHighlighter highlighter;
	private final SlayerSwapsConfig config;

	@Inject
	MenuHighlightOverlay(MenuHighlighter highlighter, SlayerSwapsConfig config)
	{
		this.highlighter = highlighter;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.objectHighlights())
		{
			return null;
		}

		graphics.setColor(config.highlightColor());
		graphics.setStroke(new BasicStroke(2));
		for (Widget w : highlighter.getHighlighted())
		{
			// Only the part its list shows, so an option scrolled half out of view isn't outlined over other panels
			Rectangle visible = w.isHidden() ? null : MenuHighlighter.visibleBounds(w, 1);
			if (visible != null)
			{
				graphics.drawRect(visible.x, visible.y, visible.width - 1, visible.height - 1);
			}
		}
		return null;
	}
}

package com.slayerswaps;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.util.Text;

/**
 * Finds the option for the current destination in open teleport menus (max cape, construction cape, fairy ring
 * log, item dialogs, Wilderness obelisk, boat teleport) and teleport spells in the spellbook. An interface only counts
 * as a menu for a route if it shows several of that route's known destinations, so a destination name appearing
 * elsewhere isn't highlighted.
 */
@Singleton
class MenuHighlighter
{
	private static final Pattern KEY_PREFIX = Pattern.compile("^[0-9a-z]\\s*[.:)]\\s+");
	private static final Pattern FAIRY_CODE = Pattern.compile("^[a-d][i-l][p-s]$");

	private static final Set<String> PORTALS = ImmutableSet.of("home", "rimmington", "taverley", "pollnivneach",
		"hosidius", "aldarin", "rellekka", "brimhaven", "yanille", "prifddinas");
	private static final Set<String> MAXCAPE = ImmutableSet.<String>builder().addAll(PORTALS)
		.add("warrior's guild", "fishing guild", "crafting guild", "farming guild", "otto's grotto",
			"feldip hills", "black chinchompas", "hunter guild", "the pandemonium", "boat", "last boat")
		.build();
	private static final Map<RouteType, Set<String>> FAMILIES = ImmutableMap.<RouteType, Set<String>>builder()
		.put(RouteType.PORTAL, PORTALS)
		.put(RouteType.MAXCAPE, MAXCAPE)
		.put(RouteType.BURNING_AMULET, ImmutableSet.of("chaos temple", "bandit camp", "lava maze"))
		.put(RouteType.RING_OF_DUELING, ImmutableSet.of("emir's arena", "castle wars", "ferox enclave", "fortis colosseum"))
		.put(RouteType.KARAMJA_GLOVES, ImmutableSet.of("gem mine", "slayer master"))
		// Quetzal Transport System landing sites, from the wiki
		.put(RouteType.QUETZAL, ImmutableSet.of("aldarin", "auburnvale", "civitas illa fortis", "hunter guild",
			"quetzacalli gorge", "sunset coast", "tal teklan", "the teomat", "cam torum", "colossal wyrm remains",
			"fortis colosseum", "kastori", "outer fortis", "salvager overlook"))
		.put(RouteType.AMULET_OF_GLORY, ImmutableSet.of("edgeville", "karamja", "draynor village", "al kharid"))
		// From the wiki's "Select Obelisk destination" interface image ("1: Level 13 Wilderness" and so on)
		.put(RouteType.OBELISK, ImmutableSet.of("level 13 wilderness", "level 19 wilderness", "level 27 wilderness",
			"level 35 wilderness", "level 44 wilderness", "level 50 wilderness"))
		.build();

	// Portal nexus destinations, from the wiki's teleport menu image and the teleport spells it can hold
	private static final Set<String> NEXUS = ImmutableSet.of("varrock", "grand exchange", "falador", "lumbridge",
		"civitas illa fortis", "kourend castle", "waterbirth island", "kharyrll", "west ardougne", "ardougne", "camelot",
		"seers' village", "watchtower", "yanille", "trollheim", "ape atoll", "catherby", "barrows", "fishing guild",
		"senntisten", "annakarl", "carrallanger", "ghorrock", "lassar", "paddewwa", "dareeyak", "salve graveyard",
		"harmony island", "cemetery", "arceuus library", "draynor manor", "battlefront", "mind altar",
		"fenkenstrain's castle", "marim", "lunar isle", "ourania", "barbarian outpost", "khazard", "ice plateau",
		"great kourend", "seers' village");

	// Jewellery box teleport menu destinations: dueling ring, games necklace, skills necklace, combat bracelet, glory
	// and ring of wealth teleports
	private static final Set<String> JEWELLERY = ImmutableSet.of("emir's arena", "castle wars", "ferox enclave",
		"fortis colosseum", "burthorpe", "barbarian outpost", "corporeal beast", "tears of guthix", "wintertodt camp",
		"fishing guild", "mining guild", "crafting guild", "cooking guild", "woodcutting guild", "farming guild",
		"warriors' guild", "champions' guild", "monastery", "ranging guild", "edgeville", "karamja", "draynor village",
		"al kharid", "miscellania", "grand exchange", "falador park", "dondakan");

	// The quetzal map's destinations are pictures: each one's model in the map's icons, as Quest Helper finds them
	private static final Map<String, Integer> QUETZAL_MAP_MODELS = ImmutableMap.<String, Integer>builder()
		.put("civitas illa fortis", 51208)
		.put("the teomat", 51205)
		.put("sunset coast", 51187)
		.put("hunter guild", 51185)
		.put("aldarin", 54547)
		.put("quetzacalli gorge", 54539)
		.put("tal teklan", 56665)
		.build();

	private final Client client;

	private static final Pattern KEYED_OPTION = Pattern.compile("^([0-9A-Za-z])\\s*[:.]\\s+(.+)$");

	private SlayerData data;
	private List<Widget> highlighted = Collections.emptyList();
	// The portal nexus teleport menu's hotkeys by destination (lower-case), from the last time it was open
	private Map<String, String> nexusKeys = Collections.emptyMap();
	// The same for the house jewellery box's teleport menu
	private Map<String, String> jewelleryKeys = Collections.emptyMap();
	// The same for the Wilderness obelisk's destination menu
	private Map<String, String> obeliskKeys = Collections.emptyMap();

	@Inject
	MenuHighlighter(Client client)
	{
		this.client = client;
	}

	void setData(SlayerData data)
	{
		this.data = data;
	}

	List<Widget> getHighlighted()
	{
		return highlighted;
	}

	Map<String, String> getNexusKeys()
	{
		return nexusKeys;
	}

	Map<String, String> getJewelleryKeys()
	{
		return jewelleryKeys;
	}

	Map<String, String> getObeliskKeys()
	{
		return obeliskKeys;
	}

	void clear()
	{
		highlighted = Collections.emptyList();
	}

	/**
	 * Rescans open interfaces for the given routes' options. Call on the client thread.
	 */
	void update(Collection<SlayerData.Route> routes)
	{
		if (routes.isEmpty())
		{
			clear();
			return;
		}

		// Labelled widgets of every open interface, grouped by interface
		Map<Integer, List<Widget>> byGroup = new HashMap<>();
		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				collect(root, byGroup);
			}
		}

		for (List<Widget> widgets : byGroup.values())
		{
			if (isNexus(widgets))
			{
				Map<String, String> keys = keys(widgets);
				nexusKeys = keys.isEmpty() ? nexusKeys : keys;
			}
			else if (countKnown(widgets, JEWELLERY) >= 3)
			{
				Map<String, String> keys = keys(widgets);
				jewelleryKeys = keys.isEmpty() ? jewelleryKeys : keys;
			}
			else if (countKnown(widgets, FAMILIES.get(RouteType.OBELISK)) >= 2)
			{
				Map<String, String> keys = keys(widgets);
				obeliskKeys = keys.isEmpty() ? obeliskKeys : keys;
			}
		}

		List<Widget> found = new ArrayList<>();
		for (SlayerData.Route route : routes)
		{
			if (route.routeType() == RouteType.QUETZAL && route.getValue() != null)
			{
				Integer model = QUETZAL_MAP_MODELS.get(route.getValue().toLowerCase());
				Widget icons = client.getWidget(InterfaceID.QuetzalMenu.ICONS);
				if (model != null && icons != null && !icons.isHidden())
				{
					quetzalIcons(icons, model, found);
				}
			}
		}
		for (Map.Entry<Integer, List<Widget>> group : byGroup.entrySet())
		{
			List<Widget> widgets = group.getValue();
			for (SlayerData.Route route : routes)
			{
				RouteType type = route.routeType();
				if (type == null || route.getValue() == null || !isMenuFor(type, route, widgets)
					// Spells only in the spellbook or portal nexus: the bank also lists tablets named after the spells
					|| type == RouteType.SPELL && group.getKey() != InterfaceID.MAGIC_SPELLBOOK && !isNexus(widgets))
				{
					continue;
				}
				for (Widget w : widgets)
				{
					if (matches(type, route.getValue(), w) && onScreen(w))
					{
						found.add(w);
					}
				}
			}
		}
		highlighted = found;
	}

	private static void quetzalIcons(Widget parent, int model, List<Widget> found)
	{
		for (Widget[] children : new Widget[][]{parent.getChildren(), parent.getDynamicChildren(), parent.getStaticChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget w : children)
			{
				if (w != null && !w.isHidden() && w.getModelId() == model && onScreen(w))
				{
					found.add(w);
				}
			}
		}
	}

	/**
	 * @return false for widgets scrolled out of their list, which are still there but clipped out of sight
	 */
	private static boolean onScreen(Widget w)
	{
		return visibleBounds(w, 0) != null;
	}

	/**
	 * @return the part of a widget (grown by a margin) its lists and panels show, or null when it's scrolled out of
	 * sight; a widget half scrolled out of a list is cut off at the list's edge
	 */
	static Rectangle visibleBounds(Widget w, int margin)
	{
		Rectangle bounds = w.getBounds();
		if (bounds == null || bounds.isEmpty())
		{
			return null;
		}
		Rectangle visible = new Rectangle(bounds.x - margin, bounds.y - margin, bounds.width + 2 * margin,
			bounds.height + 2 * margin);
		for (Widget parent = w.getParent(); parent != null; parent = parent.getParent())
		{
			Rectangle area = parent.getBounds();
			if (area != null && !area.isEmpty())
			{
				visible = visible.intersection(area);
				if (visible.isEmpty())
				{
					return null;
				}
			}
		}
		return visible;
	}

	private static void collect(Widget w, Map<Integer, List<Widget>> byGroup)
	{
		if (w == null || w.isHidden())
		{
			return;
		}

		if (!isEmpty(w.getText()) || !isEmpty(w.getName()))
		{
			byGroup.computeIfAbsent(WidgetUtil.componentToInterface(w.getId()), k -> new ArrayList<>()).add(w);
		}

		collectAll(w.getStaticChildren(), byGroup);
		collectAll(w.getDynamicChildren(), byGroup);
		collectAll(w.getNestedChildren(), byGroup);
	}

	private static void collectAll(Widget[] children, Map<Integer, List<Widget>> byGroup)
	{
		if (children != null)
		{
			for (Widget child : children)
			{
				collect(child, byGroup);
			}
		}
	}

	private boolean isMenuFor(RouteType type, SlayerData.Route route, List<Widget> widgets)
	{
		switch (type)
		{
			case FAIRY:
				return widgets.stream().filter(w -> FAIRY_CODE.matcher(label(w).replace(" ", "")).matches()).count() >= 2;
			case BOAT:
				return widgets.stream().anyMatch(w -> label(w).contains("boat"));
			case SPELL:
				// The spellbook (several widgets named after teleport spells), or a house portal nexus's teleport menu
				return widgets.stream().filter(w -> name(w).endsWith(" teleport")).count() >= 3 || isNexus(widgets);
			case ITEM:
				SlayerData.ItemData item = data == null ? null : data.getItems().get(route.getItem());
				return item != null && countKnown(widgets, lower(item.getOptions())) >= 2;
			default:
				Set<String> family = FAMILIES.get(type);
				return family != null && countKnown(widgets, family) >= 2;
		}
	}

	/**
	 * @return hotkeys of a menu's options ("1: Varrock") by option, lower-case
	 */
	private static Map<String, String> keys(List<Widget> widgets)
	{
		Map<String, String> keys = new HashMap<>();
		for (Widget w : widgets)
		{
			Matcher m = KEYED_OPTION.matcher(isEmpty(w.getText()) ? "" : Text.removeTags(w.getText()).trim());
			if (m.matches())
			{
				keys.put(m.group(2).trim().toLowerCase(), m.group(1).toUpperCase());
			}
		}
		return keys;
	}

	private static boolean isNexus(List<Widget> widgets)
	{
		// The jewellery box's menu shares a few destinations (Barbarian Outpost, Grand Exchange) with the nexus
		long nexus = countKnown(widgets, NEXUS);
		return nexus >= 2 && nexus > countKnown(widgets, JEWELLERY);
	}

	private static long countKnown(List<Widget> widgets, Set<String> known)
	{
		return widgets.stream().map(MenuHighlighter::label).filter(known::contains).distinct().count();
	}

	private static Set<String> lower(List<String> values)
	{
		Set<String> out = new HashSet<>();
		for (String v : values)
		{
			out.add(v.toLowerCase());
		}
		return out;
	}

	private static boolean matches(RouteType type, String value, Widget w)
	{
		String target = value.toLowerCase();
		switch (type)
		{
			case FAIRY:
				return label(w).replace(" ", "").equals(target);
			case BOAT:
				return label(w).contains(target);
			case SPELL:
				// The portal nexus lists the destination without "Teleport" ("6: Kourend Castle"), sometimes renamed
				return name(w).equals(target) || SlayerSwapsPlugin.isNexusOptionFor(label(w), target);
			default:
				return label(w).equals(target);
		}
	}

	/**
	 * Text of a widget, lower-cased with tags and any hotkey prefix like "1. " or "B: " removed.
	 */
	static String label(Widget w)
	{
		if (isEmpty(w.getText()))
		{
			return "";
		}
		String text = Text.removeTags(w.getText()).trim().toLowerCase();
		return KEY_PREFIX.matcher(text).replaceFirst("");
	}

	private static String name(Widget w)
	{
		return isEmpty(w.getName()) ? "" : Text.removeTags(w.getName()).trim().toLowerCase();
	}

	private static boolean isEmpty(String s)
	{
		return s == null || s.isEmpty();
	}
}

package com.slayerswaps;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * An arrow on the minimap pointing toward the task's monsters (or the way in to them, or the slayer master) once
 * the player is close enough to walk there.
 */
class MinimapArrowOverlay extends Overlay
{
	// Pixels from the player's dot on the minimap to the arrow's tail and tip, inside the minimap's edge
	private static final int TAIL = 50;
	private static final int TIP = 62;
	private static final int HEAD = 7;

	private final Client client;
	private final SlayerSwapsPlugin plugin;
	private final SlayerSwapsConfig config;

	@Inject
	MinimapArrowOverlay(Client client, SlayerSwapsPlugin plugin, SlayerSwapsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldPoint target = plugin.arrowTarget();
		WorldPoint at = plugin.playerLocation();
		Player player = client.getLocalPlayer();
		if (target == null || at == null || player == null)
		{
			return null;
		}
		// A point a few tiles toward the target, so the minimap's rotation and zoom give the direction on screen
		LocalPoint here = player.getLocalLocation();
		double dx = target.getX() - at.getX();
		double dy = target.getY() - at.getY();
		double length = Math.hypot(dx, dy);
		if (length == 0)
		{
			return null;
		}
		int step = 4 * Perspective.LOCAL_TILE_SIZE;
		LocalPoint toward = new LocalPoint(here.getX() + (int) (dx / length * step), here.getY() + (int) (dy / length * step),
			here.getWorldView());
		Point from = Perspective.localToMinimap(client, here);
		Point to = Perspective.localToMinimap(client, toward);
		if (from == null || to == null)
		{
			return null;
		}
		double sx = to.getX() - from.getX();
		double sy = to.getY() - from.getY();
		double screenLength = Math.hypot(sx, sy);
		if (screenLength == 0)
		{
			return null;
		}
		sx /= screenLength;
		sy /= screenLength;

		int tailX = (int) (from.getX() + sx * TAIL);
		int tailY = (int) (from.getY() + sy * TAIL);
		int tipX = (int) (from.getX() + sx * TIP);
		int tipY = (int) (from.getY() + sy * TIP);
		Polygon head = new Polygon();
		head.addPoint(tipX, tipY);
		head.addPoint((int) (tipX - sx * HEAD - sy * HEAD * 0.6), (int) (tipY - sy * HEAD + sx * HEAD * 0.6));
		head.addPoint((int) (tipX - sx * HEAD + sy * HEAD * 0.6), (int) (tipY - sy * HEAD - sx * HEAD * 0.6));
		int shaftEndX = (int) (tipX - sx * HEAD * 0.8);
		int shaftEndY = (int) (tipY - sy * HEAD * 0.8);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		// A dark outline first, so the arrow shows on any minimap colours
		graphics.setColor(Color.BLACK);
		graphics.setStroke(new BasicStroke(4, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.drawLine(tailX, tailY, shaftEndX, shaftEndY);
		graphics.drawPolygon(head);
		graphics.setColor(config.highlightColor());
		graphics.setStroke(new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
