 */
@Getter
@RequiredArgsConstructor
public enum RouteType
{
	RING("ring", "Slayer ring"),
	FAIRY("fairy", "Fairy ring"),
	PORTAL("portal", "House portal (construction / max cape)"),
	MAXCAPE("maxcape", "Max cape"),
	KARAMJA_GLOVES("karamja_gloves", "Karamja gloves 4"),
	BURNING_AMULET("burning_amulet", "Burning amulet"),
	RING_OF_DUELING("ring_of_dueling", "Ring of dueling"),
	AMULET_OF_GLORY("amulet_of_glory", "Amulet of glory"),
	BOAT("boat", "Teleport to Boat"),
	ITEM("item", "Teleport item"),
	SPELL("spell", "Spell or tablet"),
	OBELISK("obelisk", "Wilderness obelisk"),
	// Not a teleport of its own: the Varlamore quetzal ride some teleports are followed by
	QUETZAL("quetzal", "Quetzal");

	private final String key;
	private final String displayName;

	static RouteType forKey(String key)
	{
		for (RouteType type : values())
		{
			if (type.key.equals(key))
			{
				return type;
			}
		}
		return null;
	}
}

package com.slayerswaps;

/**
 * Short descriptions of routes, for the next teleport box, slayer helmet menus and chat messages.
 */
final class Routes
{
	private Routes()
	{
	}

	/**
	 * @return a short "Type : Destination" description, with any step after arriving
	 */
	static String describe(SlayerData data, SlayerData.Route route)
	{
		String text = describeTeleport(data, route);
		return route.getNote() == null ? text : text + ", then " + route.getNote();
	}

	/**
	 * @return a teleport's name for the slayer helmet's menus, without the item's destination, which a location only
	 * has one of: "Pendant of ates", "Max cape", "Slayer ring"; short destinations that tell teleports of one kind
	 * apart stay, like "Fairy ring : BKP" and "House : Brimhaven"
	 */
	static String shortName(SlayerData data, SlayerData.Route route)
	{
		RouteType type = route.routeType();
		if (type == null)
		{
			return describeTeleport(data, route);
		}
		switch (type)
		{
			case ITEM:
				SlayerData.ItemData item = data.getItems().get(route.getItem());
				String label = item != null ? item.getLabel() : route.getItem();
				// "Kharedst's memoirs / Book of the dead" is "Kharedst's memoirs"; "Morytania legs 3/4" is "Morytania legs"
				return label.replaceFirst(" / .*$", "").replaceFirst(" \\d/\\d$", "");
			case RING:
				return "Slayer ring";
			case MAXCAPE:
				return "Max cape";
			case KARAMJA_GLOVES:
				return "Karamja gloves";
			case AMULET_OF_GLORY:
				return "Glory";
			case RING_OF_DUELING:
				return "Dueling ring";
			case BURNING_AMULET:
				return "Burning amulet";
			case BOAT:
				return "Boat";
			default:
				return describeTeleport(data, route);
		}
	}

	/**
	 * @return a short "Type : Destination" description, such as "House : Brimhaven" or "Fairy ring : BKP"
	 */
	static String describeTeleport(SlayerData data, SlayerData.Route route)
	{
		RouteType type = route.routeType();
		String value = route.getValue();
		if (type == null)
		{
			return route.getType() + " : " + value;
		}
		switch (type)
		{
			case SPELL:
				return "Spell : " + value.replaceFirst(" Teleport$", "");
			case ITEM:
				SlayerData.ItemData item = data.getItems().get(route.getItem());
				String label = item != null ? item.getLabel() : route.getItem();
				return value == null ? label : label + " : " + value;
			case PORTAL:
				// Going home is just "Home"; a house portal is "House : Brimhaven"
				return "Home".equals(value) ? value : "House : " + value;
			case RING:
				return "Slayer ring : " + value;
			case MAXCAPE:
				return "Max cape : " + value;
			case KARAMJA_GLOVES:
				return "Karamja gloves : " + value;
			case AMULET_OF_GLORY:
				return "Glory : " + value;
			case RING_OF_DUELING:
				return "Dueling ring : " + value;
			case BURNING_AMULET:
				return "Burning amulet : " + value;
			case FAIRY:
				return "Fairy ring : " + value;
			case BOAT:
				return "Boat : " + value;
			case OBELISK:
				return "Obelisk : " + value.replaceFirst(" Wilderness$", "");
			default:
				return type.getDisplayName() + " : " + value;
		}
	}

	/**
	 * @return a location's name for display, without the wiki's disambiguation: "Death Plateau (location)" is
	 * "Death Plateau" and "Gryphons (dungeon)" is "Gryphons Dungeon"
	 */
	static String place(String location)
	{
		return location.replaceFirst(" \\(location\\)$", "").replaceFirst(" \\(dungeon\\)$", " Dungeon");
	}

	/**
	 * Stable key for remembering a chosen route in config.
	 */
	static String key(SlayerData.Route route)
	{
		return route.getType() + "|" + (route.getItem() == null ? "" : route.getItem()) + "|"
			+ (route.getValue() == null ? "" : route.getValue());
	}
}

package com.slayerswaps;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;
import net.runelite.api.coords.WorldPoint;

/**
 * Slayer tasks, the locations they're done at and the teleports that reach each location.
 * Loaded from slayer_locations.json, which is built from the OSRS wiki (see README).
 */
@Data
class SlayerData
{
	private Map<String, LocationData> locations;
	private List<TaskData> tasks;
	private List<MasterData> masters;
	private Map<String, ItemData> items;

	private transient Map<String, TaskData> taskIndex;

	@Data
	static class Route
	{
		private String type;
		private String value;
		// Catalog key for "item" and "network" routes
		private String item;
		// What to do after teleporting, such as pulling a lever
		private String note;
		// The quetzal landing site to fly to after teleporting, such as "The Teomat"
		private String quetzal;
		// Where the teleport lands, from the OSRS Wiki
		private Spot landing;
		// For a landing in a city on a map area of its own, like Prifddinas, its entrances on the surface map
		private List<Spot> entrances;
		// The landing is the wiki's pin by one of the game's own map icons, like a boat's docking point, which the
		// world map ring moves onto once the map shows it
		private boolean nearIcon;

		RouteType routeType()
		{
			return RouteType.forKey(type);
		}
	}

	@Data
	static class LocationData
	{
		private List<Route> routes;
		private boolean wilderness;
		// For places underground or otherwise apart from the surface map: the way in from the surface
		private Spot entrance;
	}

	/**
	 * A map tile, from the OSRS Wiki.
	 */
	@Data
	static class Spot
	{
		private int x;
		private int y;
		private int plane;
		// It's one of the world map's links between map areas, like a dungeon entrance's, which the map draws at the
		// tile's corner rather than its middle
		private boolean link;

		WorldPoint toWorldPoint()
		{
			return new WorldPoint(x, y, plane);
		}
	}

	@Data
	static class TaskData
	{
		private String name;
		private List<String> aliases;
		private List<String> masters;
		private boolean boss;
		private List<String> locations;
		// Konar's areas for this task: area name -> locations in it
		private Map<String, List<String>> konar;
		// The middle of the task monsters' spawns at each location
		private Map<String, Spot> spots;
		// The monsters that count for the task, as the wiki names them
		private List<String> monsters;
	}

	@Data
	static class ItemData
	{
		private String label;
		// Lower-case item name prefixes, so every charge/variant of the item matches
		private List<String> names;
		private List<String> options;
	}

	@Data
	static class MasterData
	{
		private String key;
		private String name;
		private String location;
		private List<Route> routes;
		private String note;
		// Where the master stands
		private Spot spot;
	}

	static SlayerData load(Gson gson)
	{
		try (InputStream in = SlayerData.class.getResourceAsStream("slayer_locations.json");
			Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			SlayerData data = gson.fromJson(reader, SlayerData.class);
			data.buildIndex();
			return data;
		}
		catch (IOException | NullPointerException e)
		{
			throw new IllegalStateException("Unable to load slayer_locations.json", e);
		}
	}

	private void buildIndex()
	{
		taskIndex = new HashMap<>();
		// A task's own name wins over another task's alias (Mogres also goes by "Ogres")
		for (TaskData task : tasks)
		{
			taskIndex.put(normalize(task.getName()), task);
		}
		for (TaskData task : tasks)
		{
			for (String alias : task.getAliases())
			{
				taskIndex.putIfAbsent(normalize(alias), task);
			}
		}
	}

	TaskData findTask(String name)
	{
		return name == null ? null : taskIndex.get(normalize(name));
	}

	LocationData location(String name)
	{
		return locations.get(name);
	}

	List<Route> routes(String location)
	{
		LocationData data = locations.get(location);
		return data == null || data.getRoutes() == null ? Collections.emptyList() : data.getRoutes();
	}

	MasterData master(String key)
	{
		for (MasterData master : masters)
		{
			if (master.getKey().equals(key))
			{
				return master;
			}
		}
		return null;
	}

	/**
	 * Reduces a task name to a comparable key, so "Abyssal demons", "abyssal demon" and "ABYSSAL DEMONS" all
	 * match, as do "Jellies"/"Jelly" and "Werewolves"/"Werewolf".
	 */
	static String normalize(String name)
	{
		String s = name.toLowerCase().replaceAll("[^a-z]", "");
		if (s.endsWith("ves"))
		{
			return s.substring(0, s.length() - 3) + "f";
		}
		if (s.endsWith("ies"))
		{
			return s.substring(0, s.length() - 3) + "y";
		}
		if (s.endsWith("s") && !s.endsWith("ss"))
		{
			return s.substring(0, s.length() - 1);
		}
		return s;
	}
}

