	private void checkLeftTask()
	{
		if (lastTaskKill != null && Duration.between(lastTaskKill, Instant.now()).compareTo(GUIDANCE_RETURNS_AFTER) > 0)
		{
			resumeGuidance();
		}
	}

	private void resumeGuidance()
	{
		lastTaskKill = null;
		teleportedToward = false;
		menusDirty = true;
		updateCarriedRoute();
	}

