package com.slayerswaps;

import com.google.common.collect.ImmutableSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;

/**
 * Decides which teleport items serve which routes. Most items are matched by name, so every charge count and
 * variant (eternal glory, trimmed capes, ornament kits) counts as the same item.
 */
@Singleton
class TeleportItems
{
	private static final Set<Integer> SLAYER_RINGS = ImmutableSet.of(
		ItemID.SLAYER_RING_1, ItemID.SLAYER_RING_2, ItemID.SLAYER_RING_3, ItemID.SLAYER_RING_4,
		ItemID.SLAYER_RING_5, ItemID.SLAYER_RING_6, ItemID.SLAYER_RING_7, ItemID.SLAYER_RING_8,
		ItemID.SLAYER_RING_ETERNAL);
	private static final Set<Integer> BURNING_AMULETS = ImmutableSet.of(
		ItemID.BURNING_AMULET_1, ItemID.BURNING_AMULET_2, ItemID.BURNING_AMULET_3, ItemID.BURNING_AMULET_4,
		ItemID.BURNING_AMULET_5);
	private static final Set<Integer> RINGS_OF_DUELING = ImmutableSet.of(
		ItemID.RING_OF_DUELING_1, ItemID.RING_OF_DUELING_2, ItemID.RING_OF_DUELING_3, ItemID.RING_OF_DUELING_4,
		ItemID.RING_OF_DUELING_5, ItemID.RING_OF_DUELING_6, ItemID.RING_OF_DUELING_7, ItemID.RING_OF_DUELING_8);

	private final Client client;
	private final Map<Integer, String> names = new HashMap<>();
	private SlayerData data;

	@Inject
	TeleportItems(Client client)
	{
		this.client = client;
	}

	void setData(SlayerData data)
	{
		this.data = data;
	}

	private String name(int itemId)
	{
		return names.computeIfAbsent(itemId, id -> client.getItemDefinition(id).getName().toLowerCase());
	}

	/**
	 * @return true if this item can be used for the route. Call on the client thread.
	 */
	boolean matches(int itemId, SlayerData.Route route)
	{
		RouteType type = route.routeType();
		if (itemId <= 0 || type == null)
		{
			return false;
		}

		String name = name(itemId);
		String value = route.getValue() == null ? "" : route.getValue().toLowerCase();
		switch (type)
		{
			case RING:
				return SLAYER_RINGS.contains(itemId);
			case KARAMJA_GLOVES:
				return itemId == ItemID.ATJUN_GLOVES_ELITE;
			case BURNING_AMULET:
				return BURNING_AMULETS.contains(itemId);
			case RING_OF_DUELING:
				return RINGS_OF_DUELING.contains(itemId);
			case AMULET_OF_GLORY:
				// "Amulet of glory(1-6)", "Amulet of glory(t1-t6)" and "Amulet of eternal glory"
				return name.startsWith("amulet of") && name.contains("glory");
			case PORTAL:
				// Construction cape, max cape, or a redirected house tablet like "Rimmington teleport"
				return isMaxCape(name) || name.startsWith("construct. cape") || name.equals(value + " teleport")
					|| value.equals("home") && name.equals("teleport to house");
			case MAXCAPE:
				return isMaxCape(name);
			case BOAT:
				return isMaxCape(name) || name.startsWith("sailing cape") || name.equals("teleport to boat");
			case SPELL:
				// The spell's tablet has the same name
				return name.equals(value);
			case ITEM:
				SlayerData.ItemData item = data == null ? null : data.getItems().get(route.getItem());
				if (item != null)
				{
					for (String prefix : item.getNames())
					{
						if (name.startsWith(prefix))
						{
							return true;
						}
					}
				}
				return false;
			default:
				return false;
		}
	}

	/**
	 * @return true if the item is any teleport item the plugin knows, for placing the location picker
	 */
	boolean isTeleportItem(int itemId)
	{
		if (itemId <= 0)
		{
			return false;
		}
		if (SLAYER_RINGS.contains(itemId) || BURNING_AMULETS.contains(itemId) || RINGS_OF_DUELING.contains(itemId)
			|| itemId == ItemID.ATJUN_GLOVES_ELITE)
		{
			return true;
		}
		String name = name(itemId);
		if (isMaxCape(name) || name.startsWith("construct. cape") || name.contains("teleport")
			|| (name.startsWith("amulet of") && name.contains("glory")))
		{
			return true;
		}
		if (data != null)
		{
			for (SlayerData.ItemData item : data.getItems().values())
			{
				for (String prefix : item.getNames())
				{
					if (name.startsWith(prefix))
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	/**
	 * @return true for the max cape itself: a max cape combined with another cape (fire, infernal, god capes and so
	 * on) loses its teleports
	 */
	private static boolean isMaxCape(String name)
	{
		return name.equals("max cape");
	}
}

package com.slayerswaps;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines the objects in the world that teleport to the current destination, such as fairy rings,
 * Wilderness obelisks and the Wilderness levers, and the way in to an underground task.
 */
class TeleportObjectOverlay extends Overlay
{
	// A fairy ring's mushrooms circle its tile about a tile and a half out
	private static final double FAIRY_RING_RADIUS = 1.6 * Perspective.LOCAL_TILE_SIZE;

	private final Client client;
	private final SlayerSwapsPlugin plugin;
	private final SlayerSwapsConfig config;
	private final ModelOutlineRenderer outlineRenderer;

	@Inject
	TeleportObjectOverlay(Client client, SlayerSwapsPlugin plugin, SlayerSwapsConfig config, ModelOutlineRenderer outlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlineRenderer = outlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.objectHighlights())
		{
			return null;
		}
		TileObject entrance = plugin.entranceObject();
		if (entrance != null)
		{
			// The way in to an underground task, while walking there
			outlineRenderer.drawOutline(entrance, 2, config.highlightColor(), 4);
		}
		Set<String> names = plugin.objectNamesToHighlight();
		if (names.isEmpty())
		{
			return null;
		}
		SlayerData.Route next = plugin.nextRoute();
		for (TileObject object : plugin.teleportObjects())
		{
			String name = plugin.objectName(object);
			if (names.contains(name))
			{
				if (name.equals("fairy ring"))
				{
					// Its model is mostly the butterflies above it, so circle the ring on the ground instead
					drawGroundRing(graphics, object);
				}
				else
				{
					outlineRenderer.drawOutline(object, 2, config.highlightColor(), 4);
				}
				// Where it goes, then how: its left-click or the teleport menu hotkey
				List<String> lines = plugin.objectLabel(object, name, next);
				if (lines == null)
				{
					continue;
				}
				int lineHeight = graphics.getFontMetrics().getHeight();
				for (int i = 0; i < lines.size(); i++)
				{
					Point text = object.getCanvasTextLocation(graphics, lines.get(i), 250);
					if (text != null)
					{
						Point line = new Point(text.getX(), text.getY() + (i - lines.size() + 1) * lineHeight);
						OverlayUtil.renderTextLocation(graphics, line, lines.get(i), config.highlightColor());
					}
				}
			}
		}
		return null;
	}

	private void drawGroundRing(Graphics2D graphics, TileObject object)
	{
		LocalPoint centre = object.getLocalLocation();
		Polygon ring = new Polygon();
		for (int i = 0; i < 32; i++)
		{
			double angle = 2 * Math.PI * i / 32;
			LocalPoint edge = new LocalPoint(centre.getX() + (int) (Math.cos(angle) * FAIRY_RING_RADIUS),
				centre.getY() + (int) (Math.sin(angle) * FAIRY_RING_RADIUS), centre.getWorldView());
			Point p = Perspective.localToCanvas(client, edge, object.getPlane());
			if (p == null)
			{
				return;
			}
			ring.addPoint(p.getX(), p.getY());
		}
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(config.highlightColor());
		graphics.setStroke(new BasicStroke(2));
		graphics.drawPolygon(ring);
	}
}

package com.slayerswaps;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Test;

public class SlayerDataTest
{
	private final SlayerData data = SlayerData.load(new Gson());

	@Test
	public void spotsAreForTheTasksOwnLocations()
	{
		for (SlayerData.TaskData task : data.getTasks())
		{
			if (task.getSpots() == null)
			{
				continue;
			}
			for (String location : task.getSpots().keySet())
			{
				boolean konar = task.getKonar() != null && task.getKonar().values().stream().anyMatch(l -> l.contains(location));
				assertTrue(task.getName() + ": " + location, task.getLocations().contains(location) || konar);
			}
		}
		// Warped jellies in the Catacombs, from the wiki's spawn pins
		SlayerData.Spot catacombs = data.findTask("Jellies").getSpots().get("Catacombs of Kourend");
		assertNotNull(catacombs);
		assertTrue(catacombs.getY() > 9000);
		assertNotNull(data.location("Catacombs of Kourend").getEntrance());
	}

	@Test
	public void slayerGearIsRecognised()
	{
		for (String name : new String[]{"slayer helmet (i)", "tztok slayer helmet (i)", "black mask", "black mask (10)",
			"black mask (i)", "enchanted gem", "eternal gem"})
		{
			assertTrue(name, SlayerSwapsPlugin.isSlayerGear(name));
		}
		assertTrue(SlayerSwapsPlugin.isSlayerHeadgear("black mask (5)"));
		assertFalse(SlayerSwapsPlugin.isSlayerHeadgear("eternal gem"));
		assertFalse(SlayerSwapsPlugin.isSlayerGear("gem bag"));
	}

	@Test
	public void taskNamesBecomeOneMonster()
	{
		assertEquals("jelly", SlayerSwapsPlugin.singular("jellies"));
		assertEquals("wolf", SlayerSwapsPlugin.singular("wolves"));
		assertEquals("ogre", SlayerSwapsPlugin.singular("ogres"));
		assertEquals("dagannoth", SlayerSwapsPlugin.singular("dagannoth"));
	}

	@Test
	public void everyTaskNameFindsItsOwnTask()
	{
		for (SlayerData.TaskData task : data.getTasks())
		{
			assertSame(task.getName(), task, data.findTask(task.getName()));
		}
	}

	@Test
	public void findsTasksByGameAndWikiNames()
	{
		assertEquals("Abyssal demons", data.findTask("Abyssal Demons").getName());
		assertEquals("Kurasks", data.findTask("Kurask").getName());
		assertEquals("Werewolves", data.findTask("Werewolf").getName());
		assertEquals("Jellies", data.findTask("Jelly").getName());
		assertNotNull(data.findTask("Thermonuclear smoke devil"));
		assertNull(data.findTask("Not a monster"));
	}

	@Test
	public void everySettingIsDeclaredInTheConfig()
	{
		// RuneLite only stores defaults for the config interface's own methods; an inherited setting has no value,
		// and the settings screen fails to open
		for (java.lang.reflect.Method m : SlayerSwapsConfig.class.getMethods())
		{
			if (m.isAnnotationPresent(net.runelite.client.config.ConfigItem.class))
			{
				assertEquals(m.getName(), SlayerSwapsConfig.class, m.getDeclaringClass());
			}
		}
	}

	@Test
	public void konarAreasAreKnownLocations()
	{
		for (SlayerData.TaskData task : data.getTasks())
		{
			if (task.getKonar() != null)
			{
				for (java.util.List<String> locations : task.getKonar().values())
				{
					for (String location : locations)
					{
						assertNotNull("Konar " + task.getName() + " -> " + location, data.location(location));
					}
				}
			}
		}
	}

	@Test
	public void everyRouteTypeAndLocationIsKnown()
	{
		for (SlayerData.TaskData task : data.getTasks())
		{
			for (String location : task.getLocations())
			{
				assertNotNull(task.getName() + " -> " + location, data.location(location));
				for (SlayerData.Route route : data.routes(location))
				{
					assertNotNull(location + " " + route.getType(), route.routeType());
				}
			}
		}
		for (SlayerData.MasterData master : data.getMasters())
		{
			assertNotNull(master.getKey(), data.location(master.getLocation()));
		}
		for (SlayerMaster master : SlayerMaster.values())
		{
			assertTrue(master.name(), master == SlayerMaster.NONE || master == SlayerMaster.NOT_CHOSEN || data.master(master.name()) != null);
		}
	}

	@Test
	public void defaultsUseTheBestTeleport()
	{
		assertEquals("Slayer Tower", data.findTask("Gargoyles").getLocations().get(0));
		assertEquals("Fremennik Slayer Dungeon", data.findTask("Kurask").getLocations().get(0));
		assertTrue(data.findTask("Abyssal demons").getLocations().contains("Abyssal Nexus"));
		assertTrue(data.location("Wilderness Slayer Cave").isWilderness());
		assertFalse(data.location("Slayer Tower").isWilderness());
	}
}

